package com.ganesh.fund;
import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/transactions") @CrossOrigin public class TransactionController {final TransactionRepository repo;final UserRepository users;TransactionController(TransactionRepository r,UserRepository u){repo=r;users=u;} @GetMapping public List<Transaction> all(){return repo.findAllByOrderByIdAsc();} @PostMapping public ResponseEntity<?> add(@RequestBody Transaction t){return save(t);} @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody Transaction in){var t=repo.findById(id).orElseThrow();t.date=in.date;t.type=in.type;t.person=in.person;t.description=in.description;t.amount=in.amount;return save(t);} ResponseEntity<?> save(Transaction t){if(t.amount==null||t.amount.signum()<=0)return ResponseEntity.badRequest().body(Map.of("message","Amount must be greater than zero"));if("withdraw".equals(t.type)){var all=repo.findAll();var balance=all.stream().map(x->"add".equals(x.type)?x.amount:x.amount.negate()).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add);if(t.id==null&&t.amount.compareTo(balance)>0)return ResponseEntity.badRequest().body(Map.of("message","Withdrawal cannot exceed current balance"));}t.createdBy=users.findByUsername(SecurityContextHolder.getContext().getAuthentication().getName()).orElse(null);return ResponseEntity.ok(repo.save(t));} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} @PostMapping("/reset-demo") public List<Transaction> reset(){repo.deleteAll();String[] d={"2026-09-01","2026-09-02","2026-09-03","2026-09-04","2026-09-06","2026-09-08","2026-09-10","2026-09-11"};String[] ty={"add","add","withdraw","add","withdraw","add","withdraw","add"};double[] a={4000,5000,1950,2500,1500,3000,2500,5000};for(int i=0;i<d.length;i++){Transaction t=new Transaction();t.date=java.time.LocalDate.parse(d[i]);t.type=ty[i];t.person=ty[i].equals("add")?"Donation":"Committee";t.description=ty[i].equals("add")?"Donation":"Expense";t.amount=java.math.BigDecimal.valueOf(a[i]);repo.save(t);}return repo.findAllByOrderByIdAsc();}}
